from decimal import Decimal, InvalidOperation


def split_installments(total: str, n: int) -> list[Decimal]:
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError("n must be an integer")
    if n < 1:
        raise ValueError("n must be >= 1")
    if not isinstance(total, str):
        raise ValueError("total must be a string")
    try:
        amount = Decimal(total)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid total: {total!r}") from None
    if not amount.is_finite():
        raise ValueError("total must be finite")
    if amount < 0:
        raise ValueError("total must be >= 0")
    if amount.as_tuple().exponent < -2:
        raise ValueError(f"total must have at most 2 decimal places: {total!r}")
    sign, digits, exponent = amount.as_tuple()
    int_digits = 0
    for d in digits:
        int_digits = int_digits * 10 + d
    if sign:
        int_digits = -int_digits
    # exponent >= -2 here, so exponent + 2 >= 0 and this is exact
    cents = int_digits * (10 ** (exponent + 2))
    base, remainder = divmod(cents, n)
    cent = Decimal("0.01")
    parts = []
    for i in range(n):
        part_cents = base + (1 if i < remainder else 0)
        parts.append(Decimal(part_cents).scaleb(-2).quantize(cent))
    return parts
